PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?director ?directorLabel ?place ?placeLabel WHERE {
  dbr:A_Chrysanthemum_Bursts_in_Cincoesquinas dbo:director ?director .
  ?director dbo:birthPlace ?place .
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = "en") }
  OPTIONAL { ?place rdfs:label ?placeLabel . FILTER (lang(?placeLabel) = "en") }
}

